import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_fp16.h>
#include <cuda_runtime.h>
#include <math.h>
#define TILE_K 32

__global__ void flash_attn_kernel(const half* __restrict__ Q,
                                   const half* __restrict__ K,
                                   const half* __restrict__ V,
                                   half* __restrict__ O,
                                   int batch, int heads, int seq, int dim,
                                   float scale) {
    int idx = blockIdx.x; // over batch*heads*seq
    int row = idx % seq;
    int bh = idx / seq;
    int b = bh / heads;
    int h = bh % heads;

    const half* Qp = Q + ((size_t)b * heads + h) * (size_t)seq * dim + (size_t)row * dim;
    const half* Kp = K + ((size_t)b * heads + h) * (size_t)seq * dim;
    const half* Vp = V + ((size_t)b * heads + h) * (size_t)seq * dim;
    half* Op = O + ((size_t)b * heads + h) * (size_t)seq * dim + (size_t)row * dim;

    extern __shared__ float smem[];
    float* q_sh = smem;              // dim floats
    float* score_sh = smem + dim;    // seq floats
    float* k_tile = smem + dim + seq; // seq*TILE_K floats (K tile staged in shared memory)

    __shared__ float sdata[1024];

    int tid = threadIdx.x;
    int nthreads = blockDim.x;

    // Load Q row into shared memory (vectorized half2 loads)
    // Load Q row into shared memory (vectorized float4 = 8 half loads)
    {
        const float4* Qp4 = reinterpret_cast<const float4*>(Qp);
        int dim4 = dim / 8;
        for (int i = tid; i < dim4; i += nthreads) {
            float4 qf4 = Qp4[i];
            half2 q0 = *reinterpret_cast<half2*>(&qf4.x);
            half2 q1 = *reinterpret_cast<half2*>(&qf4.y);
            half2 q2 = *reinterpret_cast<half2*>(&qf4.z);
            half2 q3 = *reinterpret_cast<half2*>(&qf4.w);
            float2 f0 = __half22float2(q0);
            float2 f1 = __half22float2(q1);
            float2 f2 = __half22float2(q2);
            float2 f3 = __half22float2(q3);
            int base = i * 8;
            q_sh[base + 0] = f0.x; q_sh[base + 1] = f0.y;
            q_sh[base + 2] = f1.x; q_sh[base + 3] = f1.y;
            q_sh[base + 4] = f2.x; q_sh[base + 5] = f2.y;
            q_sh[base + 6] = f3.x; q_sh[base + 7] = f3.y;
        }
    }
    __syncthreads();
    // Compute raw scores using shared-memory K tiling for coalesced global loads.
    // Cooperative loading maps consecutive threads to consecutive columns of the
    // same K row, producing fully coalesced global memory transactions instead of
    // the previous per-thread strided row access pattern.
    {
        float sum = 0.f;
        int num_tiles = dim / TILE_K;
        for (int t = 0; t < num_tiles; ++t) {
            int col_base = t * TILE_K;
            int half_pairs = seq * (TILE_K / 2);
            for (int l = tid; l < half_pairs; l += nthreads) {
                int row = l / (TILE_K / 2);
                int col_pair = l - row * (TILE_K / 2);
                int col = col_pair * 2;
                const half2* Kp2 = reinterpret_cast<const half2*>(Kp + (size_t)row * dim + col_base + col);
                half2 kv = *Kp2;
                float2 kf = __half22float2(kv);
                k_tile[row * TILE_K + col] = kf.x;
                k_tile[row * TILE_K + col + 1] = kf.y;
            }
            __syncthreads();
            if (tid < seq) {
                const float* krow = k_tile + tid * TILE_K;
                const float* qseg = q_sh + col_base;
                #pragma unroll
                for (int c = 0; c < TILE_K; ++c) {
                    sum += qseg[c] * krow[c];
                }
            }
            __syncthreads();
        }
        if (tid < seq) {
            score_sh[tid] = sum * scale;
        }
    }
    __syncthreads();
    // Reduce max (warp-shuffle intra-warp reduction + small cross-warp reduction)
    float maxval = -1e30f;
    for (int i = tid; i < seq; i += nthreads) {
        maxval = fmaxf(maxval, score_sh[i]);
    }
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
        maxval = fmaxf(maxval, __shfl_down_sync(0xffffffff, maxval, offset));
    }
    int warp_id = tid >> 5;
    int lane_id = tid & 31;
    int num_warps = (nthreads + 31) >> 5;
    if (lane_id == 0) sdata[warp_id] = maxval;
    __syncthreads();
    if (tid == 0) {
        float m = sdata[0];
        for (int w = 1; w < num_warps; ++w) m = fmaxf(m, sdata[w]);
        sdata[0] = m;
    }
    __syncthreads();
    float row_max = sdata[0];
    __syncthreads();
    // Compute exp and sum
    float sum_exp = 0.f;
    for (int i = tid; i < seq; i += nthreads) {
        float e = expf(score_sh[i] - row_max);
        score_sh[i] = e;
        sum_exp += e;
    }
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
        sum_exp += __shfl_down_sync(0xffffffff, sum_exp, offset);
    }
    if (lane_id == 0) sdata[warp_id] = sum_exp;
    __syncthreads();
    if (tid == 0) {
        float t = 0.f;
        for (int w = 0; w < num_warps; ++w) t += sdata[w];
        sdata[0] = t;
    }
    __syncthreads();
    float total = sdata[0];
    __syncthreads();

    // Normalize
    for (int i = tid; i < seq; i += nthreads) {
        score_sh[i] /= total;
    }
    __syncthreads();

    // Compute output: O = attn @ V (vectorized float2 loads/stores, 4 halfs per load)
    int dim4_out = dim / 4;
    for (int k4 = tid; k4 < dim4_out; k4 += nthreads) {
        int k = k4 * 4;
        float acc0 = 0.f, acc1 = 0.f, acc2 = 0.f, acc3 = 0.f;
        for (int j = 0; j < seq; ++j) {
            float s = score_sh[j];
            const float2* Vrow2 = reinterpret_cast<const float2*>(Vp + (size_t)j * dim + k);
            float2 vf2 = *Vrow2;
            half2 v0 = *reinterpret_cast<half2*>(&vf2.x);
            half2 v1 = *reinterpret_cast<half2*>(&vf2.y);
            float2 f0 = __half22float2(v0);
            float2 f1 = __half22float2(v1);
            acc0 += s * f0.x; acc1 += s * f0.y;
            acc2 += s * f1.x; acc3 += s * f1.y;
        }
        half2 o0 = __floats2half2_rn(acc0, acc1);
        half2 o1 = __floats2half2_rn(acc2, acc3);
        float2 of2;
        *reinterpret_cast<half2*>(&of2.x) = o0;
        *reinterpret_cast<half2*>(&of2.y) = o1;
        float2* Op2 = reinterpret_cast<float2*>(Op + k);
        *Op2 = of2;
    }
}

torch::Tensor flash_attention_forward(torch::Tensor Q, torch::Tensor K, torch::Tensor V) {
    TORCH_CHECK(Q.is_cuda(), "Q must be a CUDA tensor");
    TORCH_CHECK(Q.dtype() == torch::kFloat16, "Q must be float16");
    TORCH_CHECK(Q.is_contiguous() && K.is_contiguous() && V.is_contiguous(), "Inputs must be contiguous");

    int batch = Q.size(0);
    int heads = Q.size(1);
    int seq = Q.size(2);
    int dim = Q.size(3);

    auto O = torch::empty_like(Q);

    float scale = 1.0f / sqrtf((float)dim);

    int total_blocks = batch * heads * seq;
    int threads = seq; // assume power of two, matches seq_len

    size_t shared_mem_size = (size_t)(dim + seq + seq * TILE_K) * sizeof(float);

    flash_attn_kernel<<<total_blocks, threads, shared_mem_size>>>(
        reinterpret_cast<const half*>(Q.data_ptr<at::Half>()),
        reinterpret_cast<const half*>(K.data_ptr<at::Half>()),
        reinterpret_cast<const half*>(V.data_ptr<at::Half>()),
        reinterpret_cast<half*>(O.data_ptr<at::Half>()),
        batch, heads, seq, dim, scale
    );

    return O;
}
"""

